*, ::before, ::after { box-sizing: border-box; }
html, body, #root { height: 100%; }
html { text-size-adjust: 100%; }
body { margin: 0px; overflow: hidden; background: var(--bg-app); color: var(--text-1); font-family: var(--font-ui); font-size: var(--fs-sm); line-height: var(--lh-sm); font-weight: 400; -webkit-font-smoothing: antialiased; text-rendering: optimizelegibility; }
h1, h2, h3, h4, p, ul, ol, figure, blockquote, pre { margin: 0px; }
ul, ol { padding: 0px; }
button, input, textarea, select { font: inherit; color: inherit; }
button { background: none; border: 0px; padding: 0px; cursor: pointer; text-align: inherit; }
button:disabled, [aria-disabled="true"] { cursor: not-allowed; }
a { color: var(--accent); text-decoration: none; }
@media (hover: hover) {
  a[data-tape-hover] { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 3px; }
}
img, svg { display: block; }
table { border-collapse: collapse; }
::selection { background: var(--selection); color: var(--text-1); }
[data-tape-focus] { outline: none; }
[data-tape-focus-visible] { outline: 2px solid var(--accent); outline-offset: 2px; }
[tabindex="-1"][data-tape-focus-visible] { outline: none; }
* { scrollbar-width: thin; scrollbar-color: var(--scrollbar-thumb) transparent; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: var(--r-full); }
::-webkit-scrollbar-track { background: transparent; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px; }
.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.tabular { font-variant-numeric: tabular-nums; }
.eyebrow { font-size: var(--fs-2xs); line-height: var(--lh-2xs); font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-3); }
.serif { font-family: var(--font-read); font-weight: 460; letter-spacing: -0.015em; }
.t1 { color: var(--text-1); }
.t2 { color: var(--text-2); }
.t3 { color: var(--text-3); font-weight: 500; }
.clamp-1 { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.clamp-2 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.clamp-3 { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.skip-link { position: fixed; top: 8px; left: 8px; z-index: var(--z-tooltip); transform: translateY(-200%); background: var(--paper); color: var(--text-on-paper); padding: 0 var(--sp-3); height: var(--ctl-md); display: inline-flex; align-items: center; border-radius: var(--r-sm); font-weight: 500; }
.skip-link[data-tape-focus-visible] { transform: none; }
@keyframes lw-pulse { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
@keyframes lw-skeleton { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}
@keyframes lw-caret { 
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes lw-spin { 
  100% { transform: rotate(360deg); }
}
@keyframes lw-enter-up { 
  0% { opacity: 0; transform: translateY(var(--enter-move, var(--move-1))); }
  100% { opacity: 1; transform: none; }
}
@keyframes lw-enter-scale { 
  0% { opacity: 0; transform: scale(var(--scale-enter)); }
  100% { opacity: 1; transform: none; }
}
@keyframes lw-enter-right { 
  0% { opacity: 0; transform: translate(var(--move-3)); }
  100% { opacity: 1; transform: none; }
}
@keyframes lw-fade { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}
.ai-pulse { animation: lw-pulse var(--pulse-dur) ease-in-out infinite; }
.spin { animation: 0.8s linear 0s infinite normal none running lw-spin; }
@media (prefers-reduced-motion: reduce) {
  .ai-pulse, .skeleton { animation: auto ease 0s 1 normal none running none !important; }
