.palette__item .cat-dot { justify-self: center; }
.palette__item.is-active { background: var(--surface-3); color: var(--text-1); }
.palette__empty { padding: var(--sp-6) var(--sp-3); text-align: center; }
.hud { position: fixed; right: var(--sp-4); bottom: var(--sp-4); z-index: var(--z-hud); width: min(340px, -32px + 100vw); border: 1px solid var(--line-strong); border-radius: var(--r-lg); background: var(--surface-3); box-shadow: var(--shadow-pop); animation: lw-enter-up var(--dur-2) var(--ease-out); }
.hud__head { display: flex; align-items: center; gap: var(--sp-2); width: 100%; height: 40px; padding: 0 var(--sp-3); font-size: var(--fs-sm); font-weight: 500; }
.hud__head span { flex: 1 1 0%; text-align: left; }
.hud__list { list-style: none; display: grid; padding: 0 var(--sp-1) var(--sp-1); border-top: 1px solid var(--line); max-height: 260px; overflow-y: auto; }
.hud__item { display: flex; align-items: center; gap: var(--sp-1); }
.hud__open { flex: 1 1 0%; min-width: 0px; display: grid; padding: var(--sp-2); border-radius: var(--r-sm); text-align: left; }
@media (hover: hover) {
  .hud__open[data-tape-hover] { background: var(--hover-overlay); }
}
.hud__title { font-size: var(--fs-sm); }
.hud__sub { display: flex; align-items: center; gap: 4px; font-size: var(--fs-xs); }
.hud__item.is-error .hud__sub { color: var(--danger); }
.hud__item.is-completed .hud__sub { color: var(--mastery); }
html[data-study="open"] .hud { bottom: var(--sp-4); }
@media (max-width: 47.99em) {
  html:not([data-study="open"]) .hud { bottom: calc(var(--dock-h) + env(safe-area-inset-bottom) + var(--sp-2)); right: var(--sp-2); width: calc(-16px + 100vw); }
}
